<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {api,type ConnectionSettings} from '@/api';
import Button from '@/components/ui/Button.vue';import Select from '@/components/ui/Select.vue';import Modal from '@/components/ui/Modal.vue';
import {Radio,Loader2} from 'lucide-vue-next';
const props=defineProps<{settings:ConnectionSettings;running:boolean;remote:boolean}>();
const emit=defineEmits<{saved:[];notice:[text:string,bad?:boolean]}>();
const advanced=ref(false),preview=ref(false),saving=ref(false),restart=ref(false),error=ref('');const draft=ref({...props.settings});
const dirty=computed(()=>JSON.stringify(draft.value)!==JSON.stringify(props.settings));
const changes=computed(()=>Object.entries(draft.value).filter(([k,v])=>v!==props.settings[k as keyof ConnectionSettings]).map(([k,v])=>({name:({protocol:'协议','edge-ip-version':'IP 版本',region:'区域',loglevel:'日志级别'} as Record<string,string>)[k],before:props.settings[k as keyof ConnectionSettings]||'全局',after:v||'全局'})));
watch(()=>props.settings,(value,old)=>{if(JSON.stringify(draft.value)===JSON.stringify(old))draft.value={...value}},{deep:true});
function choose(protocol:string){draft.value={...props.settings,protocol};restart.value=false;error.value='';preview.value=true}
function review(){restart.value=false;error.value='';preview.value=true}
async function apply(){saving.value=true;error.value='';try{const result=await api.optimize({action:'connection',confirmed:true,settings:{...draft.value},before:{...props.settings},restart:restart.value});preview.value=false;emit('notice',result.output);emit('saved')}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
</script>
<template><section class="settings-card space-y-5"><div class="section-heading !mb-0"><div><div class="eyebrow">CONNECT IN THREE STEPS</div><h2>连接设置 · 先用推荐方案</h2><p>选择方案 → 检查变更 → 保存。没有问题时保持当前配置。</p></div><Radio class="h-5 w-5 text-primary"/></div>
 <div class="info-strip !mb-0">这些设置只控制<strong>面板主机 → Cloudflare</strong>，不控制手机到 Cloudflare 的线路。{{remote?'当前 Token 模式仍适用连接参数，转发规则以云端为准。':'转发规则和源站地址不会随连接方案改变。'}}</div>
 <div class="preset-grid"><article><strong>HTTP/2 · 默认推荐</strong><p>使用 TCP 连接 Cloudflare；本面板默认采用此方案。现有 IP/区域保持不变，仍建议按实际网络复测。</p><Button variant="outline" :disabled="saving||settings.protocol==='http2'" @click="choose('http2')">{{settings.protocol==='http2'?'当前方案 · 推荐':'预览 HTTP/2 推荐方案'}}</Button></article><article><strong>自动选择 · 备选</strong><p>交由 cloudflared 自动协商协议，可能使用 QUIC。需要时可作为对照测试，不是本面板默认值。</p><Button variant="outline" :disabled="saving||settings.protocol==='auto'" @click="choose('auto')">{{settings.protocol==='auto'?'当前方案':'预览自动方案'}}</Button></article><article><strong>QUIC · 对比备选</strong><p>使用 UDP；不同网络效果不同。需要时先保存诊断基线，再测试稳定性与延迟。</p><Button variant="outline" :disabled="saving||settings.protocol==='quic'" @click="choose('quic')">{{settings.protocol==='quic'?'当前方案':'预览 QUIC'}}</Button></article></div>
 <div class="rounded-xl bg-muted/40 p-4 text-xs leading-6 text-muted-foreground">当前：{{settings.protocol}} · IP {{settings['edge-ip-version']}} · {{settings.region||'全局'}} · 日志 {{settings.loglevel}}。若要比较方案，先点右上“访问诊断”，保留同网络测试结果。</div>
 <Button variant="ghost" @click="advanced=!advanced">{{advanced?'收起高级选项':'我了解影响，展开高级选项'}}</Button>
 <div v-if="advanced" class="space-y-4 border-t pt-4"><p class="text-xs leading-6 text-muted-foreground">高级选项默认保留现状。IPv6 需要主机真的具备 IPv6 出口；us 是区域限制，不能保证访客更快；DEBUG 可能包含请求信息。</p><div class="grid gap-4 sm:grid-cols-2"><div class="field-label">传输协议<Select v-model="draft.protocol" label="传输协议" :options="[{value:'http2',label:'HTTP/2 · 默认推荐'},{value:'auto',label:'自动 · 备选'},{value:'quic',label:'QUIC · 备选'}]"/></div><div class="field-label">IP 版本<Select v-model="draft['edge-ip-version']" label="边缘 IP 版本" :options="[{value:'4',label:'IPv4'},{value:'6',label:'IPv6'},{value:'auto',label:'自动'}]"/></div><div class="field-label">连接区域<Select v-model="draft.region" label="连接区域" :options="[{value:'',label:'全局'},{value:'us',label:'美国 us'}]"/></div><div class="field-label">日志级别<Select v-model="draft.loglevel" label="日志级别" :options="['info','warn','error','debug','fatal'].map(value=>({value,label:value}))"/></div></div><div class="flex flex-wrap gap-2"><Button variant="outline" :disabled="saving||!dirty" @click="draft={...settings}">还原未保存修改</Button><Button :disabled="saving||!dirty" @click="review">预览并保存</Button></div></div>
 <Modal v-model="preview" label="连接配置变更预览" :busy="saving"><h2 class="text-lg font-semibold">检查连接变更</h2><p v-if="!changes.length" class="info-strip mt-4">没有需要保存的变更。</p><dl class="mt-4 space-y-2"><div v-for="change in changes" :key="change.name" class="flex flex-wrap justify-between gap-2 rounded-xl bg-muted/40 p-3 text-sm"><dt>{{change.name}}</dt><dd>{{change.before}} → <strong>{{change.after}}</strong></dd></div></dl><p class="mt-4 text-xs leading-6 text-muted-foreground">保存前调用 cloudflared 校验；不通过会还原旧参数。默认仅保存，下次启动生效。勾选立即重启会短暂断开所有此隧道连接。</p><label v-if="running" class="switch-row mt-4 rounded-xl border p-3"><span class="text-xs">保存后立即重启并应用</span><input v-model="restart" class="switch-input" type="checkbox" aria-label="保存后立即重启并应用"/></label><p v-if="error" class="error-strip mt-4" role="alert">{{error}}</p><div class="mt-5 flex justify-end gap-2"><Button variant="outline" :disabled="saving" @click="preview=false">取消</Button><Button :disabled="saving||!changes.length" @click="apply"><Loader2 v-if="saving" class="h-4 w-4 animate-spin"/>确认保存{{restart?'并重启':''}}</Button></div></Modal>
 </section></template>
